n&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;lt;&lt;/span&gt;hr&lt;span class=&#34;symbol&#34;&gt;&amp;amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;br&lt;/span&gt; /&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;color: #0000BB&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;lt;&lt;/span&gt;?php&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;highlight_file&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;color: #007700&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;(&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;color: #0000BB&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;__FILE__&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;color: #007700&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;);&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;color: #0000BB&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;?&lt;span class=&#34;symbol&#34;&gt;&amp;amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;br&lt;/span&gt; /&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;lt;&lt;/span&gt;/div&lt;span class=&#34;symbol&#34;&gt;&amp;amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;br&lt;/span&gt; /&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;lt;&lt;/span&gt;/body&lt;span class=&#34;symbol&#34;&gt;&amp;amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;br&lt;/span&gt; /&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;br&lt;/span&gt; /&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;lt;&lt;/span&gt;/html&lt;span class=&#34;symbol&#34;&gt;&amp;amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;code&lt;/span&gt;&amp;gt;&lt;/span&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;能提炼出来php后端源码&lt;/p&gt;
&lt;figure class=&#34;highlight php&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;?php&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$file&lt;/span&gt; = &lt;span class=&#34;variable&#34;&gt;$_GET&lt;/span&gt;[&lt;span class=&#34;string&#34;&gt;&amp;#x27;file&amp;#x27;&lt;/span&gt;] ?? &lt;span class=&#34;string&#34;&gt;&amp;#x27;chap1.html&amp;#x27;&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 1. 黑名单过滤&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (&lt;span class=&#34;title function_ invoke__&#34;&gt;preg_match&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/http|https|env|\.\.|^\/|=\/|index|proc|input|data|convert|string|file/i&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;variable&#34;&gt;$file&lt;/span&gt;)) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;die&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;咬你哦！&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (&lt;span class=&#34;variable&#34;&gt;$file&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;title function_ invoke__&#34;&gt;ob_start&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;include&lt;/span&gt;(&lt;span class=&#34;variable&#34;&gt;$file&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;// 2. 文件包含漏洞点&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;variable&#34;&gt;$output&lt;/span&gt; = &lt;span class=&#34;title function_ invoke__&#34;&gt;ob_get_clean&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 3. 核心输出判断逻辑&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (@&lt;span class=&#34;title function_ invoke__&#34;&gt;preg_match&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;//u&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;variable&#34;&gt;$output&lt;/span&gt;)) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$output&lt;/span&gt;; &lt;span class=&#34;comment&#34;&gt;// 如果是 UTF-8 文本，直接输出&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125; &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;// 小刻不知道什么是二进制流，但是小刻觉得这里的代码古怪&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;title function_ invoke__&#34;&gt;base64_encode&lt;/span&gt;(&lt;span class=&#34;variable&#34;&gt;$output&lt;/span&gt;); &lt;span class=&#34;comment&#34;&gt;// 如果是二进制流，转 Base64 输出&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;哒哒哒哒哒！&amp;quot;&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;?&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到关键信息&lt;strong&gt;漏洞入口&lt;/strong&gt;：&lt;code&gt;?file=&lt;/code&gt; 参数，通过 &lt;code&gt;include($file)&lt;/code&gt; 触发文件包含漏洞。目标文件是 &lt;code&gt;flag.php&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;黑名单是&lt;code&gt;http&lt;/code&gt;、&lt;code&gt;https&lt;/code&gt;、&lt;code&gt;env&lt;/code&gt;、&lt;code&gt;../&lt;/code&gt;、&lt;code&gt;/&lt;/code&gt;、&lt;code&gt;index&lt;/code&gt;、&lt;code&gt;proc&lt;/code&gt;、&lt;code&gt;input&lt;/code&gt;、&lt;code&gt;data&lt;/code&gt;、&lt;code&gt;convert&lt;/code&gt;、&lt;code&gt;string&lt;/code&gt;、&lt;code&gt;file&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;需要让 output 变成二进制流，从而进入 else 得到base64输出&lt;/p&gt;
&lt;p&gt;构建一个产生二进制数据的过滤器 zlib.deflate将数据压缩成二进制&lt;/p&gt;
&lt;p&gt;最终得到payload&lt;/p&gt;
&lt;p&gt;?file&amp;#x3D;php:&amp;#x2F;&amp;#x2F;filter&amp;#x2F;zlib.deflate&amp;#x2F;resource&amp;#x3D;flag.php&lt;/p&gt;
&lt;p&gt;得到用base64表示的二进制数据&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;lZBBTsJAGIX3PcWEuG1AJ23SWMvOe5RKxQQDEVcaE7Ei1gpVQ7SSEoUoBYwFTYwEWr3M&amp;#x2F;NNx1SvY3kAXb&amp;#x2F;X+9&amp;#x2F;4vT85XS1VuRS+r22gDZXYrRW1fPxRULAiiLvF4DUt8TsQaX1C3BB5jfVWXREnUcO4os84VtVIFZTbTMMzewB2R+cVPbxAHl2BPqGuy+oQ67ah7ShYLaraYEUauxby6XNhTwByTuZV4YHrUaMTBAzx5dHhCnalcU9jgBWY2nC&amp;#x2F;hyqBtkyzO5GxNIaHLjhtQ&amp;#x2F;6TNG&amp;#x2F;rep52vBCKbRez7nvof9LYJr3fpt9CNOqMUwZkybwj2NToo7xQQtK0oGCd0JHwEe0qWz2Teivw++EYcdNOiZIy&amp;#x2F;6D+neYX7BQ&amp;#x3D;&amp;#x3D;    &lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;用Python解码&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; base64&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; zlib&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 1. 这是题目给出的 Base64 字符串&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;encoded = (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 2. Base64 解码：得到压缩后的二进制数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;compressed = base64.b64decode(encoded)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;Base64 解码成功，数据长度：&amp;quot;&lt;/span&gt;, &lt;span class=&#34;built_in&#34;&gt;len&lt;/span&gt;(compressed), &lt;span class=&#34;string&#34;&gt;&amp;quot;字节&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 3. 按原始 DEFLATE 格式解压&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;src = zlib.decompress(compressed, -&lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 4. 将解压结果转换成可读文本&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;src = src.decode(&lt;span class=&#34;string&#34;&gt;&amp;quot;utf-8&amp;quot;&lt;/span&gt;, errors=&lt;span class=&#34;string&#34;&gt;&amp;quot;replace&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;\n===== 解压得到的 PHP 源码 =====\n&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(src)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 5. 保存源码，方便之后查看&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;open&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;flag.php&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;w&amp;quot;&lt;/span&gt;, encoding=&lt;span class=&#34;string&#34;&gt;&amp;quot;utf-8&amp;quot;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; f:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    f.write(src)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;\n源码已保存到 flag.php&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;$flag &amp;#x3D; “moectf{5a3556f9-3239-063c-bad5-33f1f9696c30}”;&lt;br&gt;echo “Flag 就在上面，只有聪明的人才能看见&lt;br&gt;剩下的剧情？大概是&lt;s&gt;被小刻吃掉了&lt;/s&gt;作者偷懒没放”;&lt;br&gt;&amp;#x2F;&amp;#x2F; 这段文字的作用只是触发 zlib 压缩，你可以不管它：&lt;br&gt;&amp;#x2F;&amp;#x2F; php php php php php php php php php php&lt;br&gt;&amp;#x2F;&amp;#x2F; php php php php php php php php php php&lt;br&gt;?&amp;gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;flag是moectf{5a3556f9-3239-063c-bad5-33f1f9696c30}&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;#%E7%9B%AE%E5%BD%95&#34;&gt;返回目录&lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;reverse&#34;&gt;&lt;a href=&#34;#Reverse&#34; class=&#34;headerlink&#34; title=&#34;Reverse&#34;&gt;&lt;/a&gt;Reverse&lt;/h2&gt;&lt;h3 id=&#34;assembly-wp&#34;&gt;&lt;a href=&#34;#Assembly-WP&#34; class=&#34;headerlink&#34; title=&#34;Assembly WP&#34;&gt;&lt;/a&gt;Assembly WP&lt;/h3&gt;&lt;blockquote&gt;
&lt;p&gt;什么是汇编语言（Assembly Language）？什么是 add, mov, jne, loop？什么是寄存器？&lt;/p&gt;
&lt;/blockquote&gt;
&lt;blockquote&gt;
&lt;p&gt;阅读这一段 x86_64 风格的汇编代码，学习各种指令，并找到正确的 flag！&lt;/p&gt;
&lt;/blockquote&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;43&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;44&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;45&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;46&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;47&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;48&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;49&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;50&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;51&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;52&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;53&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;55&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;56&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;57&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;58&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;59&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;60&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;61&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;62&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;63&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;64&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;65&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;66&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;67&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;68&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;69&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;70&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;71&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;72&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;73&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;74&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;75&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;76&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;77&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;78&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;; x86-64, Intel syntax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;; rdi points to output buffer&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;start:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rdi, [buf]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rsi, [byte_404000]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401000:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     al, byte ptr [rsi]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], al&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rsi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rdi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop    loc_401000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     eax, 0x2a&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    add     eax, 0x16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    cmp     eax, 0x40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jne     loc_401080&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ebx, 0x10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    shl     ebx, 2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    cmp     eax, ebx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jne     loc_401080&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 0x39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    sub     ecx, 0x20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    cmp     ecx, 0x18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jg      loc_401050&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jmp     loc_401080&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401050:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rsi, [byte_404020]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401060:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     al, byte ptr [rsi]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    xor     al, 0x42&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], al&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rsi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rdi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop    loc_401060&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jmp     loc_4010b0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401080:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rsi, [byte_404030]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401090:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     al, byte ptr [rsi]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], al&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rsi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rdi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop    loc_401090&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_4010b0:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], 0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ret&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;byte_404000:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x6d, 0x6f, 0x65, 0x63, 0x74, 0x66, 0x7b&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x41, 0x73, 0x73, 0x65, 0x6d, 0x62, 0x31, 0x79&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x5f, 0x4c, 0x34, 0x6e, 0x67, 0x75, 0x61, 0x67, 0x65, 0x5f&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;byte_404020:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x73, 0x11, 0x1d, 0x21, 0x2d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x72, 0x2d, 0x72, 0x0d, 0x2d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x2d, 0x2e, 0x63, 0x63, 0x3f&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;byte_404030:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 0x63, 0x6f, 0x72, 0x72, 0x65, 0x63, 0x74, 0x21, 0x7d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;buf:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    db 64 dup(0)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;分析汇编代码&lt;/p&gt;
&lt;p&gt;第一部分&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;start:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rdi, [buf]          ; 把“输出框”的地址交给 rdi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rsi, [byte_404000]  ; 把“数据源”的地址交给 rsi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 25             ; 告诉计数器 ecx：我们要搬运 25 次&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401000:                     ; 开始循环搬运&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     al, byte ptr [rsi]  ; 从数据源拿 1 个字节，放进临时口袋 al&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], al  ; 把这个字节放进输出框&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rsi                 ; 数据源地址 +1（看下一个字节）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rdi                 ; 输出框地址 +1（准备写下一个）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop    loc_401000          ; ecx 自动减 1，如果不为 0，就跳回上面继续搬&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这是在把byte_404000里的十六进制数字转写成字符&lt;/p&gt;
&lt;p&gt;我们使用python&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;part1_hex = [&lt;span class=&#34;number&#34;&gt;0x6d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x6f&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x65&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x63&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x74&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x66&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x7b&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x41&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x73&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x73&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x65&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x6d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x62&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x31&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x79&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x5f&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x4c&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x34&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x6e&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x67&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x75&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x61&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x67&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x65&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x5f&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;part1_str = &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;.join([&lt;span class=&#34;built_in&#34;&gt;chr&lt;/span&gt;(b) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; b &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; part1_hex])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;第一段破解结果：&amp;quot;&lt;/span&gt;, part1_str)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到moectf{Assemb1y_L4nguage_&lt;/p&gt;
&lt;p&gt;第二部分&lt;/p&gt;
&lt;p&gt;算术题&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;mov     eax, 0x2a       ; eax = 42
add     eax, 0x16       ; eax = 42 + 22 = 64
cmp     eax, 0x40       ; 比较 64 和 64 (0x40是十六进制的64)
jne     loc_401080      ; jne = 如果不相等就跳走。结果相等，所以不跳。

mov     ebx, 0x10       ; ebx = 16
shl     ebx, 2          ; shl是左移，相当于乘以4。ebx = 16 * 4 = 64
cmp     eax, ebx        ; 再次比较 64 和 64
jne     loc_401080      ; 结果相等，所以不跳。

mov     ecx, 0x39       ; ecx = 57
sub     ecx, 0x20       ; ecx = 57 - 32 = 25
cmp     ecx, 0x18       ; 比较 25 和 24 (0x18是24)
jg      loc_401050      ; jg = 如果大于就跳转。25大于24，条件成立！跳到 loc_401050

jmp     loc_401080      ; 如果前面没跳，就掉进陷阱 loc_401080
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;第三部分进行异或&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;loc_401050:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lea     rsi, [byte_404020] ; 读第二段数据源&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     ecx, 15            ; 这次循环 15 次&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loc_401060:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     al, byte ptr [rsi]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    xor     al, 0x42           ; 把每个字节和 0x42 做“异或”运算&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    mov     byte ptr [rdi], al ; 把解密后的结果塞进输出框&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rsi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    inc     rdi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop    loc_401060&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    jmp     loc_4010b0         ; 跳去收尾（加上结束符并退出）&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;part2_encrypted = [&lt;span class=&#34;number&#34;&gt;0x73&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x11&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x1d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x21&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x2d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x72&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x2d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x72&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x0d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x2d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x2d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x2e&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x63&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x63&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x3f&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;part2_str = &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;.join([&lt;span class=&#34;built_in&#34;&gt;chr&lt;/span&gt;(b ^ &lt;span class=&#34;number&#34;&gt;0x42&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; b &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; part2_encrypted])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;第二段破解结果：&amp;quot;&lt;/span&gt;, part2_str)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;p&gt;1S_co0o0Oool!!}&lt;/p&gt;
&lt;p&gt;拼接到一起得到&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;moectf{Assemb1y_L4nguage_1S_co0o0Oool!!}&lt;/strong&gt;&lt;/p&gt;
&lt;h3 id=&#34;bbxor-wp&#34;&gt;&lt;a href=&#34;#bbxor-WP&#34; class=&#34;headerlink&#34; title=&#34;bbxor WP&#34;&gt;&lt;/a&gt;bbxor WP&lt;/h3&gt;&lt;blockquote&gt;
&lt;p&gt;小 D 在参加某知名网络安全比赛时，遇到了一道名为 bbjv 的题目，可是他苦思冥想了好久都没有做出来。赛后他发誓，再也不相信任何前缀为 bb 的题目了。&lt;/p&gt;
&lt;p&gt;那么聪明的你，能否解决这道 bbxor 呢：）&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;下载chall 4&lt;/p&gt;
&lt;p&gt;在终端查看文件类型&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;file chall4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;chall4: ELF 64-bit LSB executable, x86-64, version 1 (SYSV), dynamically linked, interpreter &amp;#x2F;lib64&amp;#x2F;ld-linux-x86-64.so.2, BuildID[sha1]&amp;#x3D;be9e403dc850f59d4d7383d9fbab3a845d891f6d, for GNU&amp;#x2F;Linux 3.2.0, not stripped&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;分析内容&lt;/p&gt;
&lt;p&gt;身份信息&lt;/p&gt;
&lt;p&gt;ELF   Linux 系统下的标准可执行文件格式&lt;/p&gt;
&lt;p&gt;64-bit  64 位程序&lt;/p&gt;
&lt;p&gt;LSB executable  小端序存储方式&lt;/p&gt;
&lt;p&gt;x86-64  CPU 架构&lt;/p&gt;
&lt;p&gt;version 1 (SYSV)  版本号&lt;/p&gt;
&lt;p&gt;运行环境&lt;/p&gt;
&lt;p&gt;dynamically linked  动态链接，需要使用系统动态库&lt;/p&gt;
&lt;p&gt;interpreter &amp;#x2F;lib64&amp;#x2F;ld-linux-x86-64.so.2  Linux 系统的“动态链接加载器”&lt;/p&gt;
&lt;p&gt;for GNU&amp;#x2F;Linux 3.2.0 编译所需的linux内核最低版本&lt;/p&gt;
&lt;p&gt;调试与逆向的关键信息&lt;/p&gt;
&lt;p&gt;BuildID[sha1]&amp;#x3D;be9e403dc850f59d4d7383d9fbab3a845d891f6d&lt;/p&gt;
&lt;p&gt;文件的哈希值&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;not stripped&lt;/strong&gt;  &lt;em&gt;说明程序保留了原来的函数名和全局变量名&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;开始运行程序&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;chmod&lt;/span&gt; +x chall4   &lt;span class=&#34;comment&#34;&gt;# 给它加上可执行权限&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;./chall4          &lt;span class=&#34;comment&#34;&gt;# 运行它&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出input 需要验证码&lt;/p&gt;
&lt;p&gt;使用linux的objdump 查看二进制文件内部结构，进行反汇编&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;objdump -M intel -d chall4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;


&lt;p&gt;完整输出很长，大部分是与解题无关的运行样板（&lt;code&gt;_init&lt;/code&gt;、&lt;code&gt;.plt&lt;/code&gt;、&lt;code&gt;deregister_tm_clones&lt;/code&gt;、&lt;code&gt;__do_global_dtors_aux&lt;/code&gt; 等），真正要看的只有 &lt;code&gt;main&lt;/code&gt; 函数这一段，其余省略。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;43&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;44&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;45&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;46&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;47&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;48&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;49&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;50&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;51&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;52&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;53&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;55&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;0000000000401156 &amp;lt;main&amp;gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401156:       f3 0f 1e fa             endbr64&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40115a:       55                      push   rbp&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40115b:       48 89 e5                mov    rbp,rsp&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40115e:       48 81 ec a0 00 00 00    sub    rsp,0xa0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401165:       48 8d 05 98 0e 00 00    lea    rax,[rip+0xe98]        # 402004 &amp;lt;_IO_stdin_used+0x4&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40116c:       48 89 c7                mov    rdi,rax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40116f:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401174:       e8 d7 fe ff ff          call   401050 &amp;lt;printf@plt&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401179:       c7 45 fc 00 00 00 00    mov    DWORD PTR [rbp-0x4],0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401180:       eb 2f                   jmp    4011b1 &amp;lt;main+0x5b&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401182:       48 8d 85 60 ff ff ff    lea    rax,[rbp-0xa0]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401189:       8b 55 fc                mov    edx,DWORD PTR [rbp-0x4]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40118c:       48 63 d2                movsxd rdx,edx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40118f:       48 c1 e2 02             shl    rdx,0x2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401193:       48 01 d0                add    rax,rdx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401196:       48 89 c6                mov    rsi,rax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401199:       48 8d 05 6c 0e 00 00    lea    rax,[rip+0xe6c]        # 40200c &amp;lt;_IO_stdin_used+0xc&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011a0:       48 89 c7                mov    rdi,rax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011a3:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011a8:       e8 b3 fe ff ff          call   401060 &amp;lt;__isoc99_scanf@plt&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011ad:       83 45 fc 01             add    DWORD PTR [rbp-0x4],0x1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011b1:       83 7d fc 23             cmp    DWORD PTR [rbp-0x4],0x23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011b5:       7e cb                   jle    401182 &amp;lt;main+0x2c&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011b7:       c7 45 f8 00 00 00 00    mov    DWORD PTR [rbp-0x8],0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011be:       eb 4b                   jmp    40120b &amp;lt;main+0xb5&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011c0:       8b 45 f8                mov    eax,DWORD PTR [rbp-0x8]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011c3:       48 98                   cdqe&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011c5:       8b 84 85 60 ff ff ff    mov    eax,DWORD PTR [rbp+rax*4-0xa0]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011cc:       83 f0 66                xor    eax,0x66&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011cf:       89 c1                   mov    ecx,eax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011d1:       8b 45 f8                mov    eax,DWORD PTR [rbp-0x8]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011d4:       48 98                   cdqe&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011d6:       48 8d 14 85 00 00 00    lea    rdx,[rax*4+0x0]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011dd:       00&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011de:       48 8d 05 5b 2e 00 00    lea    rax,[rip+0x2e5b]        # 404040 &amp;lt;cipher&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011e5:       8b 04 02                mov    eax,DWORD PTR [rdx+rax*1]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011e8:       39 c1                   cmp    ecx,eax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011ea:       74 1b                   je     401207 &amp;lt;main+0xb1&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011ec:       48 8d 05 1c 0e 00 00    lea    rax,[rip+0xe1c]        # 40200f &amp;lt;_IO_stdin_used+0xf&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011f3:       48 89 c7                mov    rdi,rax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011f6:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  4011fb:       e8 50 fe ff ff          call   401050 &amp;lt;printf@plt&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401200:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401205:       eb 23                   jmp    40122a &amp;lt;main+0xd4&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401207:       83 45 f8 01             add    DWORD PTR [rbp-0x8],0x1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40120b:       83 7d f8 23             cmp    DWORD PTR [rbp-0x8],0x23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40120f:       7e af                   jle    4011c0 &amp;lt;main+0x6a&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401211:       48 8d 05 fa 0d 00 00    lea    rax,[rip+0xdfa]        # 402012 &amp;lt;_IO_stdin_used+0x12&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401218:       48 89 c7                mov    rdi,rax&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40121b:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401220:       e8 2b fe ff ff          call   401050 &amp;lt;printf@plt&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  401225:       b8 00 00 00 00          mov    eax,0x0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40122a:       c9                      leave&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  40122b:       c3                      ret&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;401179: mov DWORD PTR [rbp-0x4],0x0&lt;/code&gt;：&lt;strong&gt;初始化变量 i &amp;#x3D; 0&lt;/strong&gt;。（&lt;code&gt;[rbp-0x4]&lt;/code&gt; 就是变量 &lt;code&gt;i&lt;/code&gt; 的家）&lt;/p&gt;
&lt;p&gt;&lt;code&gt;401180: jmp 4011b1&lt;/code&gt;：直接跳过去&lt;strong&gt;检查循环条件&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;循环体（401182 ~ 4011a8）&lt;/strong&gt;：&lt;/p&gt;
&lt;p&gt;&amp;#96;&amp;#96;lea rax, [rbp-0xa0]&amp;#96;：取出刚才开辟的 160 字节空间的&lt;strong&gt;起始地址&lt;/strong&gt;（也就是数组 input 的首地址）。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;mov edx, [rbp-0x4]&lt;/code&gt; &amp;#x2F; &lt;code&gt;shl rdx, 0x2&lt;/code&gt;：计算下标。&lt;code&gt;shl rdx, 0x2&lt;/code&gt; 就是 &lt;code&gt;i * 4&lt;/code&gt;，因为每个整数占 4 个字节。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;add rax, rdx&lt;/code&gt;：算出数组第 &lt;code&gt;i&lt;/code&gt; 个元素的&lt;strong&gt;精确地址&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;call __isoc99_scanf@plt&lt;/code&gt;：&lt;strong&gt;读取输入&lt;/strong&gt;。格式是 &lt;code&gt;%d&lt;/code&gt;（地址在 &lt;code&gt;40200c&lt;/code&gt;），把读到的数字存入数组。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;add [rbp-0x4], 1&lt;/code&gt;：&lt;code&gt;i++&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;4011b1: cmp [rbp-0x4], 0x23&lt;/code&gt; &amp;#x2F; &lt;code&gt;jle 401182&lt;/code&gt;：&lt;strong&gt;循环判断&lt;/strong&gt;。&lt;code&gt;0x23&lt;/code&gt; 换算成十进制是 &lt;strong&gt;35&lt;/strong&gt;。因为 &lt;code&gt;i&lt;/code&gt; 从 0 开始，所以这代表要读取 &lt;strong&gt;36 个整数&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;4011b7: mov DWORD PTR [rbp-0x8],0x0&lt;/code&gt;：&lt;strong&gt;初始化变量 j &amp;#x3D; 0&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;循环体（4011c0 ~ 4011e8）&lt;/strong&gt;：&lt;/p&gt;
&lt;p&gt;&lt;code&gt;mov eax, [rbp+rax*4-0xa0]&lt;/code&gt;：&lt;strong&gt;取出 input[j]&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4011cc: xor eax,0x66：&lt;/strong&gt; 把刚才取出的数字与 &lt;code&gt;0x66&lt;/code&gt;（十进制 102，字符 &lt;code&gt;&amp;#39;f&amp;#39;&lt;/code&gt;）做异或运算。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;mov ecx, eax&lt;/code&gt;：把异或后的结果暂存在 &lt;code&gt;ecx&lt;/code&gt; 里。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;lea rax, [rip+0x2e5b] # 404040 &amp;lt;cipher&amp;gt;&lt;/code&gt;： 加载名为 &lt;code&gt;cipher&lt;/code&gt; 的数组地址，地址是 &lt;code&gt;0x404040&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;mov eax, [rdx+rax*1]&lt;/code&gt;：取出 &lt;code&gt;cipher[j]&lt;/code&gt; 的值。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;cmp ecx, eax&lt;/code&gt;：&lt;strong&gt;比较&lt;/strong&gt; &lt;code&gt;input[j] ^ 0x66&lt;/code&gt; 和 &lt;code&gt;cipher[j]&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;je 401207&lt;/code&gt;：如果相等，跳过去执行 &lt;code&gt;j++&lt;/code&gt;；如果不等，继续往下走打印 &lt;code&gt;Wrong!&lt;/code&gt; 并退出。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;401207: add [rbp-0x8], 1&lt;/code&gt;：&lt;code&gt;j++&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;40120b: cmp [rbp-0x8], 0x23&lt;/code&gt; &amp;#x2F; &lt;code&gt;jle 4011c0&lt;/code&gt;：循环 36 次&lt;/p&gt;
&lt;p&gt;&lt;code&gt;401211 ~ 401220&lt;/code&gt;：如果 36 个数字全都对上了，打印 &lt;code&gt;Success!&lt;/code&gt;（地址在 &lt;code&gt;402012&lt;/code&gt;）。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;40122a: leave&lt;/code&gt; &amp;#x2F; &lt;code&gt;40122b: ret&lt;/code&gt;：打扫现场，函数返回。&lt;/p&gt;
&lt;p&gt;因此这是一个关于异或的计算程序&lt;/p&gt;
&lt;p&gt;密文在内存地址 &lt;code&gt;0x404040&lt;/code&gt;，且名称是cipher，计算方式是与0x66进行异或运算&lt;/p&gt;
&lt;p&gt;先去读取内存里的密文&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;gdb ./chall4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;x/36wx 0x404040&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;0x404040 &amp;lt;cipher&amp;gt;:      0x0000000b      0x00000009      0x00000003      0x00000005&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x404050 &amp;lt;cipher+16&amp;gt;:   0x00000012      0x00000000      0x0000001d      0x00000024&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x404060 &amp;lt;cipher+32&amp;gt;:   0x00000052      0x00000015      0x0000000f      0x00000005&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x404070 &amp;lt;cipher+48&amp;gt;:   0x00000039      0x0000001e      0x00000056      0x00000014&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x404080 &amp;lt;cipher+64&amp;gt;:   0x00000039      0x00000005      0x0000000e      0x00000007&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x404090 &amp;lt;cipher+80&amp;gt;:   0x00000057      0x0000000a      0x00000003      0x00000008&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x4040a0 &amp;lt;cipher+96&amp;gt;:   0x00000001      0x00000003      0x00000039      0x00000015&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x4040b0 &amp;lt;cipher+112&amp;gt;:  0x00000009      0x0000000a      0x00000010      0x00000003&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0x4040c0 &amp;lt;cipher+128&amp;gt;:  0x00000002      0x00000047      0x00000047      0x0000001b&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;用python进行异或运算&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;c = [&lt;span class=&#34;number&#34;&gt;0x0b&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x09&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x03&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x05&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x00&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x1d&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x24&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x52&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x15&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x0f&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x05&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x39&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x1e&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x56&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x14&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x39&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x05&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x0e&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x07&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x57&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x0a&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x03&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x08&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x01&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x03&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x39&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x15&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x09&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x0a&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x03&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x02&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x47&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x47&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0x1b&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;.join(&lt;span class=&#34;built_in&#34;&gt;chr&lt;/span&gt;(n ^ &lt;span class=&#34;number&#34;&gt;0x66&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; n &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; c))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;p&gt;moectf{B4sic_x0r_cha1lenge_solved!!}&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;#%E7%9B%AE%E5%BD%95&#34;&gt;返回目录&lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;crypto&#34;&gt;&lt;a href=&#34;#Crypto&#34; class=&#34;headerlink&#34; title=&#34;Crypto&#34;&gt;&lt;/a&gt;Crypto&lt;/h2&gt;&lt;h3 id=&#34;justxor-wp&#34;&gt;&lt;a href=&#34;#justXOR-WP&#34; class=&#34;headerlink&#34; title=&#34;justXOR WP&#34;&gt;&lt;/a&gt;justXOR WP&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;from Crypto.Util.number import long_to_bytes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flag = b&amp;#x27;moectf&amp;#123;???&amp;#125;&amp;#x27;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;# just a normal big prime&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;M = 2039129633208009090414901212304234091626233923923301042398416489123719065081065776033127561876033127924471&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;def gen_key(base, n):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    a = [base]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    for _ in range(n - 1):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        new_val = (3 * a[-1] + 2) % M&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        a.append(new_val)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    return a[-1]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;n = 10**25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;key = gen_key(1, n)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;enc = bytes([x ^ y for x, y in zip(flag, long_to_bytes(key))])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;# b&amp;#x27;it\x0bM\xfa-\xe3T&amp;#123;\xaa\x0f@\xa2\xf1@\xbd\x86e\x85\x9e\xfcp_o\x8f\xccd\x13\xceW\x13\x14\x11\x055b\xcbk\xa0&amp;#x27;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;





&lt;blockquote&gt;
&lt;p&gt;from Crypto.Util.number import long_to_bytes&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;从 &lt;code&gt;pycryptodome&lt;/code&gt; 库导入 &lt;code&gt;long_to_bytes&lt;/code&gt; 函数。它的功能是把一个&lt;strong&gt;大整数&lt;/strong&gt;转换成对应的&lt;strong&gt;字节串&lt;/strong&gt;（大端序）。例如 &lt;code&gt;long_to_bytes(0x4142)&lt;/code&gt; 得到 b’AB’&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;flag &amp;#x3D; b’moectf{???}’&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;定义明文 flag。它是一个字节串。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;M &amp;#x3D; 2039129633208009090414901212304234091626233923923301042398416489123719065081065776033127561876033127924471&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;定义一个大素数 &lt;code&gt;M&lt;/code&gt;，作为下面递推运算的&lt;strong&gt;模数&lt;/strong&gt;。题目注释说它是 “just a normal big prime”&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;def gen_key(base, n):&lt;br&gt;    a &amp;#x3D; [base]&lt;br&gt;    for _ in range(n - 1):&lt;br&gt;        new_val &amp;#x3D; (3 * a[-1] + 2) % M&lt;br&gt;        a.append(new_val)&lt;br&gt;    return a[-1]&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;生成密钥的函数。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;a = [base]&lt;/code&gt;：初始化列表，&lt;code&gt;a[0] = base&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;循环 &lt;code&gt;n-1&lt;/code&gt; 次，每次用公式 &lt;code&gt;new_val = (3 * a[-1] + 2) % M&lt;/code&gt; 计算新值并追加到列表。&lt;/p&gt;
&lt;p&gt;循环结束后 &lt;code&gt;a&lt;/code&gt; 中共有 &lt;code&gt;n&lt;/code&gt; 个元素（下标 &lt;code&gt;0&lt;/code&gt; 到 &lt;code&gt;n-1&lt;/code&gt;）。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;return a[-1]&lt;/code&gt;：返回最后一个元素，即 &lt;code&gt;a[n-1]&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;代码里的递推关系即 &lt;code&gt;a_{k+1} = 3*a_k + 2 (mod M)&lt;/code&gt;，&lt;code&gt;a_0 = 1&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;循环 n-1 次后 &lt;code&gt;return a[-1]&lt;/code&gt;，函数返回的是第 &lt;code&gt;n-1&lt;/code&gt; 项（&lt;code&gt;a_0&lt;/code&gt; 记为第 0 项）。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt; n &amp;#x3D; 10**25&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;设置迭代次数为10**25 &lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;key &amp;#x3D; gen_key(1, n)&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;调用函数，以 &lt;code&gt;base = 1&lt;/code&gt; 生成密钥，即 &lt;code&gt;key = a_{n-1}&lt;/code&gt;，其中 &lt;code&gt;a_0 = 1&lt;/code&gt;，&lt;code&gt;a_{k+1} = 3*a_k + 2 (mod M)&lt;/code&gt;。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt; enc &amp;#x3D; bytes([x ^ y for x, y in zip(flag, long_to_bytes(key))])&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;code&gt;long_to_bytes(key)&lt;/code&gt;：把大整数 &lt;code&gt;key&lt;/code&gt; 转成字节串。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;zip(flag, key_bytes)&lt;/code&gt;：把 flag 的每个字节和 key 的每个字节配对。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;x ^ y&lt;/code&gt;：逐字节&lt;strong&gt;异或&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;bytes([...])&lt;/code&gt;：把结果列表转回字节串。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt; b’it\x0bM\xfa-\xe3T{\xaa\x0f@\xa2\xf1@\xbd\x86e\x85\x9e\xfcp_o\x8f\xccd\x13\xceW\x13\x14\x11\x055b\xcbk\xa0’&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;给出了加密后的密文字节串（共 41 字节）&lt;/p&gt;
&lt;p&gt;整个加密流程是：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;用递推公式生成大整数 &lt;code&gt;key&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;把 &lt;code&gt;key&lt;/code&gt; 转成字节串。&lt;/li&gt;
&lt;li&gt;把 flag 的每个字节与 key 的对应字节&lt;strong&gt;异或&lt;/strong&gt;，得到密文 &lt;code&gt;enc&lt;/code&gt;。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;得到key就能得到flag&lt;/p&gt;
&lt;p&gt;由递推求通项：对 &lt;code&gt;a_{k+1} = 3*a_k + 2&lt;/code&gt; 两边加 1，得&lt;/p&gt;
&lt;p&gt;&lt;code&gt;a_{k+1} + 1 = 3*(a_k + 1) (mod M)&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;令 &lt;code&gt;b_k = a_k + 1&lt;/code&gt;，则 &lt;code&gt;b_k&lt;/code&gt; 是公比为 3 的等比数列，且 &lt;code&gt;b_0 = a_0 + 1 = 2&lt;/code&gt;，所以 &lt;code&gt;b_k = 2*3^k (mod M)&lt;/code&gt;，回代得&lt;/p&gt;
&lt;p&gt;&lt;code&gt;a_k = 2*3^k − 1 (mod M)&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;于是 &lt;code&gt;key = a_{n−1} = 2*3^{n−1} − 1 (mod M)&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;n−1 = 10^25 − 1&lt;/code&gt; 极大，直接算 &lt;code&gt;3^(n−1)&lt;/code&gt; 不可行，用 &lt;code&gt;pow(3, n-1, M)&lt;/code&gt; 做快速模幂（内置二进制取幂，复杂度 O(log n)）。&lt;/p&gt;
&lt;p&gt;把 &lt;code&gt;key&lt;/code&gt; 用 &lt;code&gt;long_to_bytes&lt;/code&gt; 转成字节串，与密文逐字节异或即可还原明文。脚本如下：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; Crypto.Util.number &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; long_to_bytes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 题目给定的参数 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;M = &lt;span class=&#34;number&#34;&gt;2039129633208009090414901212304234091626233923923301042398416489123719065081065776033127561876033127924471&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;n = &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;**&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;enc = &lt;span class=&#34;string&#34;&gt;b&amp;#x27;it\x0bM\xfa-\xe3T&amp;#123;\xaa\x0f@\xa2\xf1@\xbd\x86e\x85\x9e\xfcp_o\x8f\xccd\x13\xceW\x13\x14\x11\x055b\xcbk\xa0&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 第一步：求 key ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通项公式：a_k = 2 * 3^k - 1 (mod M)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# key = a_&amp;#123;n-1&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;key = (&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * &lt;span class=&#34;built_in&#34;&gt;pow&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, n - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, M) - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;) % M&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 第二步：整数转字节串 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;key_bytes = long_to_bytes(key)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 第三步：逐字节异或还原明文 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flag_bytes = &lt;span class=&#34;built_in&#34;&gt;bytes&lt;/span&gt;([c ^ k &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; c, k &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(enc, key_bytes)])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 第四步：解码输出 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(flag_bytes.decode())&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到flag &lt;strong&gt;moectf{a_simple_sequence_problem_for_u}&lt;/strong&gt;&lt;/p&gt;
&lt;h3 id=&#34;wsl_sign1n-wp&#34;&gt;&lt;a href=&#34;#wsl-Sign1n-WP&#34; class=&#34;headerlink&#34; title=&#34;wsl_Sign1n WP&#34;&gt;&lt;/a&gt;wsl_Sign1n WP&lt;/h3&gt;&lt;blockquote&gt;
&lt;p&gt; sage老师，我还记得你。一次一次，将我格基约减。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;blockquote&gt;
&lt;p&gt; 根据指引，在wsl里安装sage，运行脚本。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;根据指示，在wsl里配置好sage&lt;/p&gt;
&lt;p&gt;输入&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sage wsl_sage_gate_0026.sage&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到&lt;/p&gt;
&lt;p&gt;moectf{woW_you_successfully_installed_1t_103}&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;#%E7%9B%AE%E5%BD%95&#34;&gt;返回目录&lt;/a&gt;&lt;/p&gt;

 &lt;p&gt;Welcome to &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9oZXhvLmlvLw==&#34;&gt;Hexo&lt;/span&gt;! This is your very first post. Check &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9oZXhvLmlvL2RvY3Mv&#34;&gt;documentation&lt;/span&gt; for more info. If you get any problems when using Hexo, you can find the answer in &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9oZXhvLmlvL2RvY3MvdHJvdWJsZXNob290aW5nLmh0bWw=&#34;&gt;troubleshooting&lt;/span&gt; or you can ask me on &lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly9naXRodWIuY29tL2hleG9qcy9oZXhvL2lzc3Vlcw==&#34;&gt;GitHub&lt;/span&gt;.&lt;/p&gt;
&lt;h2 id=&#34;quick-start&#34;&gt;&lt;a href=&#34;#Quick-Start&#34; class=&#34;headerlink&#34; title=&#34;Quick Start&#34;&gt;&lt;/a&gt;Quick Start&lt;/h2&gt;&lt;h3 id=&#34;create-a-new-post&#34;&gt;&lt;a href=&#34;#Create-a-new-post&#34; class=&#34;headerlink&#34; title=&#34;Create a new post&#34;&gt;&lt;/a&gt;Create a new post&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;$ hexo new &lt;span class=&#34;string&#34;&gt;&amp;quot;My New Post&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

